import pandas as pd

def point_in_time(table, as_of_date):
    known = table[table['as_of'] <= pd.Timestamp(as_of_date)]
    known = known.sort_values('as_of')
    latest = known.groupby(['ticker', 'quarter_end']).tail(1)
    return latest.sort_values(['ticker', 'quarter_end'])['eps'].tolist()
